examples.template:
NavigationStack {
    MonarchCommentsPanel(
        threads,
        filter: $filter,
        selectedThreadID: $selectedThreadID,
        now: {{now|date}},
        onClose: {},
        onReply: { id, text in
            guard let index = threads.firstIndex(where: { $0.id == id }) else { return }
            let thread = threads[index]
            let reply = MonarchCommentThreadComment(id: UUID().uuidString, author: "You", body: text, createdAt: .now, canDelete: true)
            threads[index] = MonarchCommentsPanelThread(id: id, comments: thread.comments + [reply], quote: thread.quote, isResolved: thread.isResolved)
        },
        onResolvedChange: { id, isResolved in
            guard let index = threads.firstIndex(where: { $0.id == id }) else { return }
            let thread = threads[index]
            threads[index] = MonarchCommentsPanelThread(
                id: id,
                comments: thread.comments,
                quote: thread.quote,
                isResolved: isResolved
            )
        },
        onDeleteComment: { id, commentID in
            guard let index = threads.firstIndex(where: { $0.id == id }) else { return }
            let thread = threads[index]
            threads[index] = MonarchCommentsPanelThread(
                id: id,
                comments: thread.comments.filter { $0.id != commentID },
                quote: thread.quote,
                isResolved: thread.isResolved
            )
        }
    )
}
.frame(height: 480)

